// spec: specs/premium-store.md (раздел 3.5)
// seed: tests/seed.reg1.spec.ts
// ЗАМЕЧАНИЕ: на живой странице 19.11 строки итога («₪209.70 ל-3 חודשים» / «₪239.40 ל-6 חודשים») нет — смена выбора видна только по выделению плитки
// (рамка #C76EEA); кнопка остаётся «לשדרג ל-Premium». Проверки итога по тексту поэтому не включены.
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/reg1-r12.json'), colorScheme: 'dark' });

test.describe('Раунд 13: тарифы Premium (#0fec32 #05baf0)', () => {
  test('Экран тарифов: 89.90/69.90/39.90, -22%/-56%, итог, «מה כלול» 50/2/30 @iphone @prod-safe', async ({ page }) => {
    const purchaseRequests: string[] = [];
    page.on('request', (r) => {
      if (/purchase|payment|checkout/i.test(r.url())) purchaseRequests.push(r.url());
    });

    // 1. 👑 в шапке «גילוי» → «חנות», область «Magnet Premium».
    await page.goto('/discover');
    await page.getByRole('button', { name: 'חנות' }).click();
    await expect(page).toHaveURL(/\/paywall/);
    await expect(page.getByText('Magnet Premium', { exact: true })).toBeVisible();

    // 2. Посмотреть плитки; выбрать «חודש», «6 חודשים», «3 חודשים».
    const t1 = page.getByTestId('price-tile-1m');
    const t3 = page.getByTestId('price-tile-3m');
    const t6 = page.getByTestId('price-tile-6m');
    const selected = /C76EEA/;
    await expect(t1).toContainText('₪89.90');
    await expect(t3).toContainText('₪69.90');
    await expect(t6).toContainText('₪39.90');
    for (const t of [t1, t3, t6]) await expect(t).toContainText('לחודש');
    await expect(t3).toContainText('-22%');
    await expect(t6).toContainText('-56%');
    await expect(t3).toHaveClass(selected);
    await expect(t1).not.toHaveClass(selected);
    await expect(t6).not.toHaveClass(selected);

    await t1.click();
    await expect(t1).toHaveClass(selected);
    await expect(t3).not.toHaveClass(selected);
    await t6.click();
    await expect(t6).toHaveClass(selected);
    await expect(t1).not.toHaveClass(selected);
    await t3.click();
    await expect(t3).toHaveClass(selected);
    await expect(t6).not.toHaveClass(selected);

    // 3. Прокрутить «מה כלול». Кнопку «לשדרג ל-Premium» не нажимать.
    await expect(page.getByText('מה כלול', { exact: true })).toBeVisible();
    await expect(page.getByText('50 סופר לייק בחודש', { exact: true })).toBeVisible();
    await expect(page.getByText('2 בוסטים בחודש', { exact: true })).toBeVisible();
    await expect(page.getByText('30 חזרות לאחור בחודש', { exact: true })).toBeVisible();
    await expect(page.getByText('אפשר לבטל בכל עת')).toHaveCount(0);
    await expect(page.getByRole('button', { name: 'לשדרג ל-Premium' })).toBeVisible();
    expect(purchaseRequests, 'запросов покупки нет').toEqual([]);
  });
});
